def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    points = [(c, r) for r in range(h) for c in range(w) if grid[r][c] != bg]

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    pts = sorted(set(points))
    if len(pts) < 2:
        return [row[:] for row in grid]

    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    hull = lower[:-1] + upper[:-1]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue
            p = (c, r)
            if len(hull) == 2:
                a, b = hull
                if cross(a, b, p) == 0 and min(a[0], b[0]) <= c <= max(a[0], b[0]) and min(a[1], b[1]) <= r <= max(a[1], b[1]):
                    out[r][c] = 3
            else:
