    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Connect marker cells that share a row.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != background]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3

    # Connect marker cells that share a column.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != background]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3

